const DEFAULT_CLINIC_ID = 'smilecare';
// The chat widget can pass ?clinic_id=... ; n8n surfaces query params under metadata on some versions.
const j = $json;
const fromMeta = j.metadata?.clinic_id || j.query?.clinic_id || j.clinic_id || '';
const clinic_id = (fromMeta && String(fromMeta).trim()) || DEFAULT_CLINIC_ID;
return { json: { clinic_id, chatInput: j.chatInput, sessionId: j.sessionId } };

const wanted = $('Resolve clinic_id').first().json.clinic_id;
const chat = $('Resolve clinic_id').first().json;
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r.clinic_id).trim() === String(wanted).trim());

if (!row) { throw new Error(`No Clinics row found for clinic_id='${wanted}'. Add a row to the Clinics tab.`); }
if (!row.pinecone_namespace || !row.sheet_id) { throw new Error(`Clinics row for '${wanted}' is missing pinecone_namespace or sheet_id.`); }

const toBool = v => v === true || String(v).toUpperCase() === 'TRUE' || String(v) === '1';
const toNum = (v, d) => { const n = parseFloat(v); return isNaN(n) ? d : n; };

return [{ json: {
  clinic_id: row.clinic_id,
  clinic_name: row.clinic_name || '',
  address: row.address || '',
  staff_email: row.staff_email || '',
  staff_phone: row.staff_phone || '',
  twilio_from: row.twilio_from || '',
  pinecone_index: row.pinecone_index || 'dental-clinic-kb',
  pinecone_namespace: row.pinecone_namespace,
  sheet_id: row.sheet_id,
  drive_folder_id: row.drive_folder_id || '',
  hours_json: row.hours_json || '{}',
  after_hours_message: row.after_hours_message || 'We are currently closed. Our team will follow up during business hours.',
  sms_enabled_patient: toBool(row.sms_enabled_patient),
  sms_enabled_staff: toBool(row.sms_enabled_staff),
  pinecone_min_score: toNum(row.pinecone_min_score, 0.78),
  test_mode: toBool(row.test_mode),
  chatInput: chat.chatInput,
  sessionId: chat.sessionId
} }];
